function renderClassScale() {
  for (const el of document.querySelectorAll('[data-class-length]')) {
    el.textContent = fmt(CLASSES[el.dataset.classLength].lenM);
  }
  const rows = [
    [CLASSES.P10000.name, CLASSES.P10000.lenM, CLASSES.P10000.diaM],
    ['Lions Gate Bridge main span', 472, 0],
    [CLASSES.P1000.name, CLASSES.P1000.lenM, CLASSES.P1000.diaM],
    ['LZ 129 Hindenburg', 245, 41],
    [CLASSES.P100.name, CLASSES.P100.lenM, CLASSES.P100.diaM],
    ['Boeing 747-400', 70.7, 0],
    ['A person', 1.8, 0],
  ];
  let y = 20;
  const drawing = rows.map(([name, length, diameter]) => {
    const width = length * .9, height = Math.max(diameter * .9, 2);
    const row = `<text x="16" y="${y}" fill="currentColor" font-size="14">${name}: ${fmt(length, Number.isInteger(length) ? 0 : 1)} m</text>` +
      `<rect x="16" y="${y + 12}" width="${width}" height="${height}" rx="${height / 2}" fill="none" stroke="currentColor"/>`;
    y += height + 60;
    return row;
  }).join('');
  const svg = $('classScale');
  svg.setAttribute('viewBox', `0 0 880 ${y}`);
  svg.setAttribute('aria-label', rows.map(([name, length]) => `${name}: ${fmt(length, Number.isInteger(length) ? 0 : 1)} metres`).join('; '));
  svg.innerHTML = drawing;
}
renderClassScale();
